        /* Handle wrap around case */
        /* Wait for pv_buf_rd to consume first job_size number of bytes
         * from the beginning of job queue
         */
        ret = (IHEVCD_ERROR_T)IHEVCD_FAIL;
    }

    ps_jobq->i4_terminate = 0;

    rettmp = ihevcd_jobq_unlock(ps_jobq);

